def solve():
    for n in range(3, 1000):
        val = 2**n - 3
        if val < 0:
            continue
        # Check if val is a power of 5
        # val = 5^k
        # We can check this by repeatedly dividing by 5
        temp = val
        if temp == 0:
            continue
        k = 0
        while temp > 1 and temp % 5 == 0:
            temp //= 5
            k += 1
        if temp == 1:
            print(f"n={n}, k={k}")

solve()

